<span class="line"><span style="color:#C678DD;">        VALUES</span><span style="color:#ABB2BF;"> (TG_TABLE_NAME, </span><span style="color:#98C379;">&#39;DELETE&#39;</span><span style="color:#ABB2BF;">, to_jsonb(OLD));</span></span>
